package it.financemanager.infrastructure.security;import it.financemanager.application.port.out.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;@Component public class SpringSecurityAdapter implements CurrentActorPort,PasswordPort{private final PasswordEncoder encoder;public SpringSecurityAdapter(PasswordEncoder e){encoder=e;}public String email(){return SecurityContextHolder.getContext().getAuthentication().getName();}public String encode(String raw){return encoder.encode(raw);}public boolean matches(String raw,String encoded){return encoder.matches(raw,encoded);}}
